const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'u = x/h = 0' },
      { kind: 'text', payload: 'u = x/h = 1/2' },
      { kind: 'text', payload: 'u = x/h = 1' },
      { kind: 'text', payload: 'x = 0' },
      { kind: 'text', payload: 'x = h/2' },
      { kind: 'text', payload: 'x = h' },
      { kind: 'text', payload: '瓶口基准线（水平）' },
      { kind: 'text', payload: '木塞' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: '位移 x = u·h' },
      { kind: 'text', payload: 'u=1 时木塞底部到达瓶口' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var marginX = Math.max(24, W * 0.06);
    var usable = W - 2 * marginX;
    var panelW = usable / 3;
    var baselineY = H * 0.54;
    var corkH = Math.min(H * 0.26, panelW * 0.55);
    var corkW = Math.max(16, Math.min(panelW * 0.22, corkH * 0.55));
    var neckDepth = corkH * 1.15;
    var neckHalf = corkW / 2 + Math.max(6, corkW * 0.25);
    var stageU = [0, 0.5, 1];
    var paths = [];
    var children = [];

    function rect(x, y, w, h) {
      return [['M', x, y], ['L', x + w, y], ['L', x + w, y + h], ['L', x, y + h], ['Z']];
    }
    function line(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }
    function addPath(id, commands, fill, strokeWidth) {
      paths.push({ id: id, commands: commands });
      children.push({ type: 'path', pathId: id, fill: fill, stroke: { width: strokeWidth } });
    }
    function addLabel(contentIndex, x, y, hAlign, vAlign, color) {
      children.push({
        type: 'label',
        contentId: metrics[contentIndex].contentId,
        anchor: { x: x, y: y },
        hAlign: hAlign,
        vAlign: vAlign,
        color: color
      });
    }

    for (var i = 0; i < 3; i++) {
      var left = marginX + i * panelW;
      var right = left + panelW;
      var cx = (left + right) / 2;
      var pad = panelW * 0.12;
      var u = stageU[i];
      var corkTop = baselineY - u * corkH;
      var corkBottom = corkTop + corkH;
      var x0 = cx - corkW / 2;

      addPath('baseline_' + i, line(left + pad, baselineY, right - pad, baselineY), '#26354a', 2.5);
      addPath('neckL_' + i, line(cx - neckHalf, baselineY, cx - neckHalf, baselineY + neckDepth), '#5c6b7a', 2);
      addPath('neckR_' + i, line(cx + neckHalf, baselineY, cx + neckHalf, baselineY + neckDepth), '#5c6b7a', 2);
      addPath('cork_' + i, rect(x0, corkTop, corkW, corkH), '#d8a35a', 2.5);

      if (u > 0) {
        var ax = cx + corkW / 2 + Math.max(18, corkW * 0.6);
        var initialBottom = baselineY + corkH;
        var currentBottom = baselineY + corkH - u * corkH;
        addPath('disp_' + i, visualSdk.arrow(ax, initialBottom, ax, currentBottom), '#c0392b', 2);
      }
    }

    var firstCx = marginX + panelW / 2;
    var dimX = firstCx - corkW / 2 - Math.max(24, corkW * 0.5);
    addPath('h_dim', visualSdk.arrow(dimX, baselineY, dimX, baselineY + corkH), '#26354a', 1.8);

    for (var j = 0; j < 3; j++) {
      var left2 = marginX + j * panelW;
      var right2 = left2 + panelW;
      var cx2 = (left2 + right2) / 2;
      addLabel(j, cx2, H * 0.12, 'center', 'bottom', '#1f2937');
      addLabel(3 + j, cx2, H * 0.18, 'center', 'bottom', '#374151');
    }
    addLabel(6, marginX, baselineY - 10, 'left', 'bottom', '#26354a');
    addLabel(7, firstCx, baselineY + corkH / 2, 'center', 'middle', '#3b2a16');
    addLabel(8, dimX - 8, baselineY + corkH / 2, 'right', 'middle', '#26354a');
    addLabel(9, W - marginX, H * 0.90, 'right', 'bottom', '#4b5563');
    addLabel(10, W / 2, H * 0.97, 'center', 'bottom', '#4b5563');

    return {
      schemaVersion: 1,
      sceneId: 'cork-pulling-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
